<script setup>
import { ref, reactive, computed, onMounted, onUnmounted, nextTick } from 'vue';
import { useI18n } from 'vue-i18n';
import MobileSliderInput from '@/mobile/components/mobile-slider-input.vue';
import MobileImageUploader from '@/mobile/components/mobile-image-uploader.vue';
import MobileDropdownSlider from '@/mobile/components/mobile-dropdown-slider.vue';
import MobileDropdown from '@/mobile/components/mobile-dropdown.vue';
import MobileLImg from '@/mobile/components/mobile-l-img.vue';
import { useMediaGenerationStore } from '@/store/modules/media-generation';
import { IMAGE_OPERATIONS } from '@/types/media-tool';

// 变量区域
const { t } = useI18n();
const mediaStore = useMediaGenerationStore();

// 当前模块的 key
const MODULE_KEY = IMAGE_OPERATIONS.ENHANCE;
const imageUploaderRef = ref(null);
const qualitySelectorAreaRef = ref(null);

// 响应式变量
const isAdvancedVisible = ref(false);
const isAnimating = ref(false);
const contentOpacity = ref(1);
const isHandFixDropdownOpen = ref(false);
const showQualitySelectorHeight = ref(0);
const formData = reactive({
  uploadedImage: null,
  scaleValue: 2.0,
  prompt: '',
  negativePrompt: '',
  creativity: 0.3,
  handFix: 'disabled',
  seed: ''
});

// 计算属性
const handFixOptions = computed(() => [
  { value: 'disabled', label: t('disabled') },
  { value: 'handsOnly', label: t('handsOnly') },
  { value: 'imageAndHands', label: t('imageAndHands') }
]);

const isFormValid = computed(() => {
  return !!(
    formData.uploadedImage && 
    formData.scaleValue && 
    formData.creativity !== null &&
    formData.handFix
  );
});



// 方法
const updateQualitySelectorHeight = () => {
  showQualitySelectorHeight.value = qualitySelectorAreaRef.value ? qualitySelectorAreaRef.value.offsetHeight : 0;
};

const toggleAdvanced = () => {
  if (isAdvancedVisible.value) {
    isAnimating.value = true;
    contentOpacity.value = 0;
    setTimeout(() => {
      isAdvancedVisible.value = false;
      isAnimating.value = false;
      // 在状态变化后重新计算高度
      nextTick(() => {
        updateQualitySelectorHeight();
      });
    }, 300);
  } else {
    isAdvancedVisible.value = true;
    isAnimating.value = true;
    nextTick(() => {
      contentOpacity.value = 1;
      // 在状态变化后重新计算高度
      updateQualitySelectorHeight();
      setTimeout(() => {
        isAnimating.value = false;
      }, 300);
    });
  }
};

const toggleHandFixDropdown = () => {
  isHandFixDropdownOpen.value = !isHandFixDropdownOpen.value;
};

const selectHandFixOption = (option) => {
  formData.handFix = option.value;
  isHandFixDropdownOpen.value = false;
};

const onHandFixChange = (option) => {
  formData.handFix = option.value;
  console.log('Hand fix changed to:', option.value);
};

const handleChangeImage = () => {
  if (imageUploaderRef.value) {
    const uploaderElement = imageUploaderRef.value.$el.querySelector('input[type="file"]');
    if (uploaderElement) {
      uploaderElement.click();
    }
  }
};

const handleDeleteImage = () => {
  if (imageUploaderRef.value) {
    imageUploaderRef.value.reset();
  }
  formData.uploadedImage = null;
};

const handleGenerate = () => {
  if (isFormValid.value) {
    const generateData = {
      imageUrl: formData.uploadedImage?.url || formData.uploadedImage,
      scale: formData.scaleValue,
      prompt: formData.prompt || undefined,
      negativePrompt: formData.negativePrompt || undefined,
      creativity: formData.creativity,
      handFix: formData.handFix,
      seed: formData.seed || undefined
    };
    console.log('Generate image with data:', generateData);
  }
};

const onImageUploadSuccess = (uploadResult) => {
  // 处理图片URL - 确保包含完整的OSS路径
  const baseUrl = import.meta.env.VITE_APP_OSS_PIC_PATH || '';
  const imageUrl = uploadResult.url;
  const fullImageUrl = imageUrl.startsWith('http') ? imageUrl : baseUrl + imageUrl;
  
  // 更新uploadResult中的url为完整路径
  const updatedResult = {
    ...uploadResult,
    url: fullImageUrl
  };
  
  formData.uploadedImage = updatedResult;
  console.log('Image uploaded successfully:', updatedResult);
};

const onImageUploadRemove = () => {
  formData.uploadedImage = null;
  console.log('Image removed');
};

const onScaleInput = (value, event) => {
  formData.scaleValue = parseFloat(value);
  
};

const onScaleChange = (value, event) => {
  formData.scaleValue = parseFloat(value);
  console.log('Scale changed to:', value);
};

const onCreativityInput = (value, event) => {
  formData.creativity = parseFloat(value);
  
};

const onCreativityChange = (value, event) => {
  formData.creativity = parseFloat(value);
  console.log('Creativity changed to:', value);
};





// 获取存储的生成结果
const loadGenerationResult = () => {
  const result = mediaStore.getGenerationResult(MODULE_KEY);
  if (result && result.imageUrl) {
    console.log('Found stored image from Pinia:', result.imageUrl);
    
    // 处理图片URL - 确保包含完整的OSS路径
    const baseUrl = import.meta.env.VITE_APP_OSS_PIC_PATH || '';
    const imageUrl = result.imageUrl;
    const fullImageUrl = imageUrl.startsWith('http') ? imageUrl : baseUrl + imageUrl;
    
    // 直接设置formData中的图片数据
    formData.uploadedImage = fullImageUrl
    
    // 清除生成结果，避免重复使用
    mediaStore.clearGenerationResult(MODULE_KEY);
  }
};

// 生命周期
onMounted(() => {
  // 检测Pinia中是否有生成的图片
  loadGenerationResult();
  
  // 初始化质量选择器区域高度
  nextTick(() => {
    updateQualitySelectorHeight();
  });
});

onUnmounted(() => {

});
</script>

