<template>
  <div class="mobile-dropdown-slider" :class="{ 'mobile-dropdown-slider--disabled': disabled }">
    <!-- Current Value 触发按钮 -->
    <div 
      ref="triggerRef"
      class="mobile-dropdown-slider__trigger"
      :class="{ 'mobile-dropdown-slider__trigger--open': isOpen }"
      @click="toggleSlider"
    >
      <div class="mobile-dropdown-slider__trigger-text">{{ triggerText }}: {{ formatValue(currentValue) }}{{ unit }}</div>
      <div class="mobile-dropdown-slider__trigger-icon">
        <!-- 设置图标 -->
        <mobile-l-img 
          :src="'/static/mobile_images/setting-config.png'" 
          w="12px" 
          h="12px"
          fit="contain"
        />
      </div>
    </div>
    
    <!-- 滑块容器 - 可展开收起 -->
    <div 
      v-show="isOpen"
      class="mobile-dropdown-slider__dropdown"
      :style="{ 
        '--arrow-position': arrowPosition,
        'bottom': dropdownBottom
      }"
      @click.stop
    >
      <!-- 滑块输入组件 -->
      <mobile-slider-input
        ref="sliderInputRef"
        :current-value="currentValue"
        :min="min"
        :max="max"
        :step="step"
        :disabled="disabled"
        :show-labels="showLabels"
        :show-current-value="showCurrentValue"
        :precision="precision"
        @on-input="onInput"
        @on-change="onChange"
      />
    </div>
    
    <!-- 遮罩层 - 点击关闭 -->
    <div 
      v-show="isOpen"
      class="mobile-dropdown-slider__mask"
      @click="closeSlider"
    ></div>
  </div>
</template>

<script setup>
import { ref, computed, watch, onMounted, onUnmounted, nextTick } from 'vue';
import MobileLImg from '@/mobile/components/mobile-l-img.vue';
import MobileSliderInput from '@/mobile/components/mobile-slider-input.vue';

// props区域
const props = defineProps({
  modelValue: {
    type: Number,
    default: 0
  },
  min: {
    type: Number,
    default: 0
  },
  max: {
    type: Number,
    default: 100
  },
  step: {
    type: Number,
    default: 1
  },
  disabled: {
    type: Boolean,
    default: false
  },
  showLabels: {
    type: Boolean,
    default: true
  },
  showCurrentValue: {
    type: Boolean,
    default: false
  },
  precision: {
    type: Number,
    default: 2
  },
  triggerText: {
    type: String,
    default: 'Scale'
  },
  unit: {
    type: String,
    default: 'x'
  }
});

// emits区域
const emit = defineEmits(['update:modelValue', 'onChange']);

// 变量区域
const triggerRef = ref(null);
const sliderInputRef = ref(null);
const currentValue = ref(props.modelValue);
const isOpen = ref(false);
const triggerWidth = ref(0);
const triggerLeft = ref(0); // 触发按钮距离屏幕左边的距离
const triggerTop = ref(0); // 触发按钮距离屏幕顶部的距离

// 计算属性区域
// 计算三角箭头位置 - 指向触发按钮中心
const arrowPosition = computed(() => {
  if (triggerLeft.value > 0 && triggerWidth.value > 0) {
    // 触发按钮中心点相对于屏幕的位置
    const triggerCenter = triggerLeft.value + (triggerWidth.value / 2);
    // 下拉容器左边距 (屏幕居中)
    const dropdownLeft = 16; // (100vw - (100vw - 32px)) / 2 = 16px
    // 箭头相对于下拉容器的位置
    return `${triggerCenter - dropdownLeft}px`;
  }
  return '50%'; // 降级值：下拉容器中心
});

// 计算下拉容器的底部位置
const dropdownBottom = computed(() => {
  if (triggerTop.value > 0) {
    // 屏幕高度 - 触发按钮顶部位置 + 8px 间距
    return `${window.innerHeight - triggerTop.value + 8}px`;
  }
  return 'calc(100% + 8px)'; // 降级值
});

// watch区域
watch(
  () => props.modelValue,
  (newValue) => {
    if (newValue !== currentValue.value) {
      currentValue.value = newValue;
    }
  },
  { immediate: true }
);

// 自定义事件区域
const onInput = (newValue) => {
  currentValue.value = newValue;
  emit('update:modelValue', newValue);
};

const onChange = (newValue) => {
  emit('onChange', newValue);
};

// 点击事件区域
const toggleSlider = () => {
  if (props.disabled) return;
  isOpen.value = !isOpen.value;
  
  // 下拉框打开时，更新度量信息
  if (isOpen.value) {
    // 使用 nextTick 确保DOM已更新
    nextTick(() => {
      updateTriggerPosition();
      // 通知子组件更新度量信息
      if (sliderInputRef.value) {
        sliderInputRef.value.initMetrics();
      }
    });
  }
};

const closeSlider = () => {
  isOpen.value = false;
};

// 业务逻辑区域
const updateTriggerPosition = () => {
  if (triggerRef.value) {
    const rect = triggerRef.value.getBoundingClientRect();
    triggerWidth.value = rect.width;
    triggerLeft.value = rect.left;
    triggerTop.value = rect.top;
  }
};

// resize事件处理函数
const handleResize = () => {
  updateTriggerPosition();
};

// 数据解析区域
const formatValue = (value) => {
  return Number(value).toFixed(props.precision);
};

// 周期函数区域
onMounted(() => {
  // 初始化时测量触发按钮位置信息
  nextTick(() => {
    updateTriggerPosition();
  });
  
  // 监听窗口大小变化，重新测量
  window.addEventListener('resize', handleResize);
});

onUnmounted(() => {
  window.removeEventListener('resize', handleResize);
});

// 导出区域
defineExpose({
  currentValue,
  isOpen,
  toggleSlider,
  closeSlider,
  updateTriggerPosition
});
</script>

