  font-weight: 400;
  line-height: 1.714;
  color: #333333;
  text-align: left;
}

.mobile-dropdown-slider__trigger-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 12px;
  height: 12px;
  flex-shrink: 0;
  
  // 图片容器的过渡效果
  transition: transform 0.2s ease;
}

// 下拉容器 - 在按钮上方弹出，屏幕居中显示
.mobile-dropdown-slider__dropdown {
  position: fixed;
  width: calc(100vw - 32px);
  left: 16px; // 屏幕居中：(100vw - (100vw - 32px)) / 2 = 16px
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-radius: 12px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1);
  z-index: 1000;
  animation: slideUp 0.2s ease-out;
  
  // 底部三角箭头指向触发按钮中心（外层边框）
  &::after {
    content: '';
    position: absolute;
    top: 100%;
    left: var(--arrow-position, 56.5px); // 动态计算的触发按钮中心位置
    transform: translateX(-50%);
    width: 0;
    height: 0;
    border-left: 8px solid transparent;
    border-right: 8px solid transparent;
    border-top: 8px solid #E5E7EB; // 边框颜色
    z-index: 1;
    filter: drop-shadow(0 1px 1px rgba(0, 0, 0, 0.05)); // 轻微阴影
  }
  
  // 内部三角箭头（覆盖边框，形成边框效果）
  &::before {
    content: '';
    position: absolute;
    top: calc(100% - 1px);
    left: var(--arrow-position, 56.5px); // 动态计算的触发按钮中心位置
    transform: translateX(-50%);
    width: 0;
    height: 0;
    border-left: 7px solid transparent;
    border-right: 7px solid transparent;
    border-top: 7px solid #FFFFFF; // 背景颜色
    z-index: 2;
  }
}

@keyframes slideUp {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

// 遮罩层
.mobile-dropdown-slider__mask {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: transparent;
  z-index: 999;
}

// 禁用状态
.mobile-dropdown-slider--disabled {
  .mobile-dropdown-slider__trigger {
    background: #F5F5F5;
    border-color: #E5E7EB;
    cursor: not-allowed;
    
    &:hover {
      background: #F5F5F5;
      border-color: #E5E7EB;
    }
  }
  
  .mobile-dropdown-slider__trigger-text {
    color: #9CA3AF;
  }
  
  .mobile-dropdown-slider__trigger-icon {
    opacity: 0.5;
  }
}
</style> 